"use strict";(globalThis.webpackChunkmy_website||=[]).push([[18786],{62307(e){e.exports=JSON.parse('{"slug":"genesis-block","title":"Genesis Block","short":"The very first block of a blockchain, kickstarting the ledger that every subsequent block extends.","category":"general","aliases":["Block 0"],"mentalModel":null,"related":["byron","ada","block"],"sources":[],"link":"/genesis","level":"intermediate","body":"The very first block of a blockchain. It is not produced like the others; instead it is hard-coded into the protocol and ships with the initial state of the ledger.\\n\\nCardano\'s genesis launched the Byron era on September 23, 2017 and defined the initial allocation of ada from voucher sales held in Asia between October 2015 and January 2017, plus the genesis entities\' share. From that starting point, every block since has extended the same continuous chain."}')}}]);